//go:build windows

package capture

import (
	"encoding/base64"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"
	"unicode/utf16"

	"github.com/BeBorq/Pentrail/internal/hooks"
)

// Codex iteration 03, finding 4: the automatic PowerShell profile block must
// not wrap batch invocations (-CommandWithArgs/-cwa, -ec, -en, ... were not
// recognised) and must keep wrapping real interactive windows.
//
// Isolation: no real profile is touched and no recorder is started. The block
// is generated by the same code `setup` uses, written to a temp profile and
// dot-sourced explicitly; "pentrail" is a stub .cmd that only appends its
// arguments to calls.txt and exits 1 (so even a wrongly wrapped process never
// starts a session). Every process runs in a real ConPTY, i.e. with a real
// console — under plain exec the block would skip itself because the
// console is redirected, and the test would prove nothing.

type psFixture struct {
	dir, stub, calls, profile, shell string
}

func newPSFixture(t *testing.T, shell string) *psFixture {
	t.Helper()
	dir := t.TempDir()
	f := &psFixture{dir: dir, shell: shell,
		stub:    filepath.Join(dir, "pentrail stub.cmd"),
		calls:   filepath.Join(dir, "calls.txt"),
		profile: filepath.Join(dir, "profil testowy.ps1")}
	if err := os.WriteFile(f.stub, []byte("@echo %*>>\"%~dp0calls.txt\"\r\n@exit /b 1\r\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(f.profile, []byte("\ufeff"+hooks.PowerShellAutoStart(f.stub, shell, "")), 0o600); err != nil {
		t.Fatal(err)
	}
	return f
}

func (f *psFixture) stubCalls() string { b, _ := os.ReadFile(f.calls); return string(b) }

func psEncode(s string) string {
	u := utf16.Encode([]rune(s))
	b := make([]byte, 0, 2*len(u))
	for _, v := range u {
		b = append(b, byte(v), byte(v>>8))
	}
	return base64.StdEncoding.EncodeToString(b)
}

func psShells(t *testing.T) []string {
	var out []string
	for _, n := range []string{"powershell.exe", "pwsh.exe"} {
		if p, err := exec.LookPath(n); err == nil {
			out = append(out, p)
		}
	}
	if len(out) == 0 {
		t.Skip("no PowerShell")
	}
	return out
}

func supportsCWA(shell string) bool {
	return exec.Command(shell, "-NoLogo", "-NoProfile", "-NonInteractive", "-cwa", "exit 0").Run() == nil
}

// runBatch starts shell with args in a ConPTY, waits for the process to end
// on its own (no hang) and returns screen text and exit code.
func runBatch(t *testing.T, shell string, args []string) (string, int) {
	t.Helper()
	s := openScreen(t, shell, args)
	select {
	case <-s.done:
	case <-time.After(60 * time.Second):
		t.Fatalf("%s %q did not finish (hang or waiting for input); screen %q", filepath.Base(shell), args, s.text())
	}
	code, err := s.p.Wait()
	if err != nil {
		t.Fatal(err)
	}
	return s.text(), code
}

func TestNativePowerShellBatchFlagsAreNotWrapped(t *testing.T) {
	for _, shell := range psShells(t) {
		name := filepath.Base(shell)
		t.Run(name, func(t *testing.T) {
			f := newPSFixture(t, shell)
			dot := ". '" + strings.ReplaceAll(f.profile, "'", "''") + "'"
			script := filepath.Join(f.dir, "skrypt.ps1")
			// a script whose own arguments look like host options
			if err := os.WriteFile(script, []byte("\ufeff"+dot+"\r\nWrite-Output ('SCRIPT_'+'ARGS:' + ($args -join ','))\r\nexit 3\r\n"), 0o600); err != nil {
				t.Fatal(err)
			}
			type tc struct {
				label string
				args  []string
				want  string
				code  int
			}
			enc := func(code string) string { return psEncode(dot + "; " + code) }
			cases := []tc{
				{"-ec", []string{"-NoLogo", "-NoProfile", "-ec", enc("Write-Output ('EC_'+'OK'); exit 5")}, "EC_OK", 5},
				{"-e", []string{"-NoLogo", "-NoProfile", "-e", enc("Write-Output ('E_'+'OK'); exit 6")}, "E_OK", 6},
				{"-en", []string{"-NoLogo", "-NoProfile", "-en", enc("Write-Output ('EN_'+'OK'); exit 4")}, "EN_OK", 4},
				{"-EncodedCommand", []string{"-NoLogo", "-NoProfile", "-EncodedCommand", enc("Write-Output ('ENC_'+'OK'); exit 8")}, "ENC_OK", 8},
				{"-c", []string{"-NoLogo", "-NoProfile", "-c", dot + "; Write-Output ('C_'+'OK'); exit 9"}, "C_OK", 9},
				{"-noni -Command", []string{"-NoLogo", "-NoProfile", "-noni", "-Command", dot + "; Write-Output ('NONI_'+'OK')"}, "NONI_OK", 0},
				{"-f with host-like script args", []string{"-NoLogo", "-NoProfile", "-ExecutionPolicy", "Bypass", "-f", script, "-NoExit", "-Interactive"}, "SCRIPT_ARGS:-NoExit,-Interactive", 3},
			}
			if supportsCWA(shell) {
				cases = append(cases,
					tc{"-cwa", []string{"-NoLogo", "-NoProfile", "-cwa", ". $args[0]; Write-Output ('CWA_'+'OK:' + $args[1]); exit 7", f.profile, "x y"}, "CWA_OK:x y", 7},
					tc{"-CommandWithArgs", []string{"-NoLogo", "-NoProfile", "-CommandWithArgs", ". $args[0]; Write-Output ('CWAF_'+'OK:' + $args[1]); exit 7", f.profile, "z"}, "CWAF_OK:z", 7},
				)
			} else {
				t.Logf("%s has no -CommandWithArgs; those cases not run", name)
			}
			for _, c := range cases {
				before := f.stubCalls()
				out, code := runBatch(t, shell, c.args)
				if !strings.Contains(strings.ReplaceAll(out, "\r\n", ""), c.want) {
					t.Fatalf("%s %s: output %q lacks %q", name, c.label, out, c.want)
				}
				if code != c.code {
					t.Fatalf("%s %s: exit code %d, want %d", name, c.label, code, c.code)
				}
				if got := f.stubCalls(); got != before {
					t.Fatalf("%s %s: batch invocation was wrapped (pentrail called: %q)", name, c.label, got[len(before):])
				}
				t.Logf("PS_BATCH %s %s output=ok exit=%d wrapped=false", name, c.label, code)
			}
		})
	}
}

// Real interactive windows are still wrapped — also with value-taking host
// options whose values must not be mistaken for anything else.
func TestNativePowerShellInteractiveIsStillWrapped(t *testing.T) {
	for _, shell := range psShells(t) {
		name := filepath.Base(shell)
		variants := [][]string{
			{"-NoLogo", "-NoProfile"},
			{"-NoLogo", "-NoProfile", "-WindowStyle", "Normal", "-ExecutionPolicy", "Bypass", "-NoExit"},
		}
		if strings.EqualFold(name, "pwsh.exe") {
			variants = append(variants, []string{"-NoLogo", "-NoProfile", "-WorkingDirectory", "", "-wd", ""})
		}
		for _, v := range variants {
			v := v
			t.Run(name+" "+strings.Join(v, " "), func(t *testing.T) {
				f := newPSFixture(t, shell)
				args := append([]string(nil), v...)
				for i := range args {
					if args[i] == "" {
						args[i] = f.dir
					}
				}
				s := openScreen(t, shell, args)
				s.send(t, ". '"+strings.ReplaceAll(f.profile, "'", "''")+"'")
				until := time.Now().Add(40 * time.Second)
				for !strings.Contains(f.stubCalls(), "__auto-check") {
					if time.Now().After(until) {
						t.Fatalf("interactive window was not wrapped; screen %q", s.text())
					}
					time.Sleep(50 * time.Millisecond)
				}
				s.send(t, "Write-Output ('STILL_'+'HERE')")
				s.wait(t, "STILL_HERE") // stub refused: the window keeps working
				if strings.Contains(f.stubCalls(), "start") {
					t.Fatalf("session start attempted although __auto-check failed: %q", f.stubCalls())
				}
				s.send(t, "exit 0")
				select {
				case <-s.done:
				case <-time.After(20 * time.Second):
					t.Fatalf("window did not close: %q", s.text())
				}
				t.Logf("PS_INTERACTIVE %s %q auto_check_called=true", name, args)
			})
		}
	}
}
